package edu.neumaned.queueadt;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.Random;

/**
 * Run this class (Run As > Java Application) to check your work.
 * It prints PASS or FAIL for every check and a score for each part.
 * Do NOT edit this file.
 */
public class TeamTester {
    private static final int[] earned = new int[5];
    private static final int[] possible = new int[5];

    private interface Check { boolean run() throws Exception; }

    private static void check(int part, int points, String name, Check c) {
        possible[part] += points;
        String result;
        try {
            if (c.run()) {
                earned[part] += points;
                result = "PASS (+" + points + ")  ";
            } else {
                result = "FAIL        ";
            }
        } catch (UnsupportedOperationException e) {
            result = "FAIL (TODO) ";
        } catch (Throwable t) {
            result = "FAIL (" + t.getClass().getSimpleName() + ") ";
        }
        System.out.println("  " + result + name);
    }

    private static boolean throwsNoSuchElement(Runnable r) {
        try {
            r.run();
            return false;
        } catch (NoSuchElementException e) {
            return true;
        }
    }

    private static String drainFront(DequeInterface<Integer> d) {
        StringBuilder sb = new StringBuilder();
        while (!d.isEmpty()) {
            sb.append(d.removeFront()).append(' ');
        }
        return sb.toString().trim();
    }

    private static String drainBack(DequeInterface<Integer> d) {
        StringBuilder sb = new StringBuilder();
        while (!d.isEmpty()) {
            sb.append(d.removeBack()).append(' ');
        }
        return sb.toString().trim();
    }

    // ---------------------------------------------------------------- Part 1
    private static void part1() {
        System.out.println("Part 1: CircularArrayDeque");
        check(0, 5, "new deque is empty; not empty after an add", () -> {
            CircularArrayDeque<Integer> d = new CircularArrayDeque<>();
            boolean a = d.isEmpty();
            d.addToBack(1);
            return a && !d.isEmpty();
        });
        check(0, 5, "addToBack then removeFront gives first-in-first-out order", () -> {
            CircularArrayDeque<Integer> d = new CircularArrayDeque<>();
            for (int i = 1; i <= 3; i++) d.addToBack(i);
            return drainFront(d).equals("1 2 3");
        });
        check(0, 5, "addToFront then removeBack (queue order) and then removeFront (stack order)", () -> {
            CircularArrayDeque<Integer> d = new CircularArrayDeque<>();
            for (int i = 1; i <= 3; i++) d.addToFront(i);
            boolean a = drainBack(d).equals("1 2 3");
            for (int i = 1; i <= 3; i++) d.addToFront(i);
            return a && drainFront(d).equals("3 2 1");
        });
        check(0, 5, "peekFront and peekBack do not remove anything", () -> {
            CircularArrayDeque<Integer> d = new CircularArrayDeque<>();
            d.addToBack(5);
            d.addToBack(6);
            d.addToFront(4);
            return d.peekFront() == 4 && d.peekBack() == 6 && d.peekFront() == 4 && drainFront(d).equals("4 5 6");
        });
        check(0, 5, "all four remove/peek methods throw NoSuchElementException when empty", () -> {
            CircularArrayDeque<Integer> d = new CircularArrayDeque<>();
            boolean ok = throwsNoSuchElement(d::removeFront) && throwsNoSuchElement(d::removeBack)
                      && throwsNoSuchElement(d::peekFront) && throwsNoSuchElement(d::peekBack);
            d.addToBack(1);
            d.removeBack();
            return ok && throwsNoSuchElement(d::removeFront);
        });
        check(0, 5, "capacity doubles 4 -> 8 -> 16 when the array is full, items stay in order", () -> {
            CircularArrayDeque<Integer> d = new CircularArrayDeque<>();
            for (int i = 1; i <= 4; i++) d.addToBack(i);
            boolean a = d.capacity() == 4;
            d.addToBack(5);
            boolean b = d.capacity() == 8;
            for (int i = 6; i <= 9; i++) d.addToBack(i);
            return a && b && d.capacity() == 16 && drainFront(d).equals("1 2 3 4 5 6 7 8 9");
        });
        check(0, 5, "resizing works after the items have wrapped around, from either end", () -> {
            CircularArrayDeque<Integer> d = new CircularArrayDeque<>();
            for (int i = 1; i <= 4; i++) d.addToBack(i);
            d.removeFront();
            d.removeFront();
            d.addToBack(5);
            d.addToBack(6);            // wrapped, array is full again
            d.addToBack(7);            // resize here
            boolean a = drainFront(d).equals("3 4 5 6 7");
            CircularArrayDeque<Integer> e = new CircularArrayDeque<>();
            for (int i = 1; i <= 5; i++) e.addToFront(i);   // resize triggered by addToFront
            return a && e.capacity() == 8 && drainFront(e).equals("5 4 3 2 1");
        });
        check(0, 5, "clear() empties the deque and returns to capacity 4; random test against java.util.ArrayDeque", () -> {
            CircularArrayDeque<Integer> d = new CircularArrayDeque<>();
            for (int i = 0; i < 20; i++) d.addToBack(i);
            d.clear();
            if (!d.isEmpty() || d.capacity() != 4) return false;
            Deque<Integer> ref = new ArrayDeque<>();
            Random rnd = new Random(274);
            for (int step = 0; step < 3000; step++) {
                int op = rnd.nextInt(6);
                if (op == 0 || op == 1) {
                    d.addToBack(step); ref.addLast(step);
                } else if (op == 2 || op == 3) {
                    d.addToFront(step); ref.addFirst(step);
                } else if (op == 4 && !ref.isEmpty()) {
                    if (!d.removeFront().equals(ref.removeFirst())) return false;
                } else if (op == 5 && !ref.isEmpty()) {
                    if (!d.removeBack().equals(ref.removeLast())) return false;
                }
                if (!ref.isEmpty() && (!d.peekFront().equals(ref.peekFirst()) || !d.peekBack().equals(ref.peekLast()))) return false;
                if (d.isEmpty() != ref.isEmpty()) return false;
            }
            return true;
        });
    }

    // ---------------------------------------------------------------- Part 2
    private static void part2() {
        System.out.println("Part 2: PalindromeChecker");
        check(1, 4, "\"A man, a plan, a canal: Panama\" is a palindrome", () ->
            PalindromeChecker.isPalindrome("A man, a plan, a canal: Panama"));
        check(1, 4, "\"Hello\" and \"ab\" are not palindromes", () ->
            !PalindromeChecker.isPalindrome("Hello") && !PalindromeChecker.isPalindrome("ab"));
        check(1, 4, "empty string, punctuation only, and one character are palindromes", () ->
            PalindromeChecker.isPalindrome("") && PalindromeChecker.isPalindrome("?!, ") && PalindromeChecker.isPalindrome("x"));
        check(1, 4, "digits count: \"12321\" yes, \"12345\" no, \"No 'x' in Nixon\" yes", () ->
            PalindromeChecker.isPalindrome("12321") && !PalindromeChecker.isPalindrome("12345")
            && PalindromeChecker.isPalindrome("No 'x' in Nixon"));
        check(1, 4, "odd and even lengths: \"Was it a car or a cat I saw?\" yes, \"Madam, I'm Adam\" yes, \"abca\" no", () ->
            PalindromeChecker.isPalindrome("Was it a car or a cat I saw?") && PalindromeChecker.isPalindrome("Madam, I'm Adam")
            && !PalindromeChecker.isPalindrome("abca"));
    }

    // ---------------------------------------------------------------- Part 3
    private static int sign(int x) { return Integer.compare(x, 0); }

    private static void part3() {
        System.out.println("Part 3: Patient and TriageRoom");
        check(2, 4, "Patient.compareTo: lower severity number comes first", () -> {
            Patient urgent = new Patient("U", 1, 9);
            Patient minor = new Patient("M", 4, 1);
            return sign(urgent.compareTo(minor)) == -1 && sign(minor.compareTo(urgent)) == 1;
        });
        check(2, 4, "Patient.compareTo: equal severity, earlier arrival comes first; identical = 0", () -> {
            Patient a = new Patient("A", 2, 3);
            Patient b = new Patient("B", 2, 7);
            return sign(a.compareTo(b)) == -1 && sign(b.compareTo(a)) == 1 && a.compareTo(new Patient("C", 2, 3)) == 0;
        });
        check(2, 4, "TriageRoom treats Bob, Di, Cy, Ann, Ed for the sample arrivals", () -> {
            TriageRoom r = new TriageRoom();
            r.arrive("Ann", 3); r.arrive("Bob", 1); r.arrive("Cy", 2); r.arrive("Di", 1); r.arrive("Ed", 3);
            StringBuilder sb = new StringBuilder();
            while (!r.isEmpty()) sb.append(r.treatNext()).append(' ');
            return sb.toString().trim().equals("Bob Di Cy Ann Ed");
        });
        check(2, 4, "arrivals after treatments still get the right priority", () -> {
            TriageRoom r = new TriageRoom();
            r.arrive("A", 2); r.arrive("B", 2);
            String first = r.treatNext();
            r.arrive("C", 2); r.arrive("D", 1);
            boolean ok = first.equals("A") && r.treatNext().equals("D") && r.treatNext().equals("B") && r.treatNext().equals("C");
            TriageRoom many = new TriageRoom();
            for (int i = 0; i < 12; i++) many.arrive("n" + i, 2);   // same severity: must come out in arrival order
            for (int i = 0; i < 12; i++) {
                if (!many.treatNext().equals("n" + i)) return false;
            }
            return ok;
        });
        check(2, 4, "peekNext does not remove; size/isEmpty are right; empty room throws NoSuchElementException", () -> {
            TriageRoom r = new TriageRoom();
            boolean ok = r.isEmpty() && r.size() == 0 && throwsNoSuchElement(r::treatNext) && throwsNoSuchElement(r::peekNext);
            r.arrive("X", 5); r.arrive("Y", 3);
            return ok && r.size() == 2 && r.peekNext().equals("Y") && r.size() == 2 && !r.isEmpty();
        });
    }

    // ---------------------------------------------------------------- Part 4
    private static List<String> reference(List<String> names, int passes) {
        List<String> people = new ArrayList<>(names);
        List<String> out = new ArrayList<>();
        int idx = 0;
        while (!people.isEmpty()) {
            idx = (idx + passes) % people.size();
            out.add(people.remove(idx));
            if (!people.isEmpty()) idx %= people.size();
        }
        return out;
    }

    private static void part4() {
        System.out.println("Part 4: HotPotato");
        List<String> five = Arrays.asList("A", "B", "C", "D", "E");
        check(3, 4, "elimination order for [A,B,C,D,E] with 2 passes is C A E B D", () ->
            HotPotato.eliminationOrder(five, 2).equals(Arrays.asList("C", "A", "E", "B", "D")));
        check(3, 4, "winner for [A,B,C,D,E] with 2 passes is D", () -> HotPotato.winner(five, 2).equals("D"));
        check(3, 4, "0 passes: the front player is out each round, so the last name wins", () ->
            HotPotato.eliminationOrder(five, 0).equals(five) && HotPotato.winner(five, 0).equals("E"));
        check(3, 4, "one player: that player wins; the input list is not modified", () -> {
            List<String> one = new ArrayList<>(Arrays.asList("Solo"));
            List<String> big = new ArrayList<>(five);
            HotPotato.eliminationOrder(big, 3);
            return HotPotato.winner(one, 7).equals("Solo") && big.equals(five);
        });
        check(3, 4, "matches an independent simulation for many sizes and pass counts; bad input throws IllegalArgumentException", () -> {
            for (int n = 1; n <= 12; n++) {
                List<String> names = new ArrayList<>();
                for (int i = 0; i < n; i++) names.add("p" + i);
                for (int k = 0; k <= 9; k++) {
                    if (!HotPotato.eliminationOrder(names, k).equals(reference(names, k))) return false;
                }
            }
            boolean empty = false, negative = false;
            try { HotPotato.winner(new ArrayList<String>(), 1); } catch (IllegalArgumentException e) { empty = true; }
            try { HotPotato.winner(five, -1); } catch (IllegalArgumentException e) { negative = true; }
            return empty && negative;
        });
    }

    public static void main(String[] args) {
        part1();
        part2();
        part3();
        part4();
        System.out.println();
        System.out.println("Part 1 (deque)      : " + earned[0] + " / " + possible[0]);
        System.out.println("Part 2 (palindrome) : " + earned[1] + " / " + possible[1]);
        System.out.println("Part 3 (triage)     : " + earned[2] + " / " + possible[2]);
        System.out.println("Part 4 (hot potato) : " + earned[3] + " / " + possible[3]);
        int e = earned[0] + earned[1] + earned[2] + earned[3];
        int p = possible[0] + possible[1] + possible[2] + possible[3];
        System.out.println("Total               : " + e + " / " + p);
    }
}
